import{_ as r,c as o,o as a,a5 as t}from"./chunks/framework.CUJoMJm2.js";const m=JSON.parse('{"title":"SBP Error Model (v1)","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbp/errors.md","filePath":"protocols/sbp/errors.md","lastUpdated":1768070912000}'),i={name:"protocols/sbp/errors.md"};function l(s,e,c,d,n,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="sbp-error-model-v1" tabindex="-1">SBP Error Model (v1) <a class="header-anchor" href="#sbp-error-model-v1" aria-label="Permalink to “SBP Error Model (v1)”">​</a></h1><p>Defines canonical error semantics for <code>@sideband/protocol</code>, independent of transport. Error frames are part of the public contract; transports MAY also surface transport-native errors (e.g. WebSocket close codes) but must map protocol failures to <code>ErrorFrame</code>.</p><h2 id="error-taxonomy" tabindex="-1">Error taxonomy <a class="header-anchor" href="#error-taxonomy" aria-label="Permalink to “Error taxonomy”">​</a></h2><ul><li>Protocol errors (1000–1999): <code>ProtocolViolation</code>, <code>UnsupportedVersion</code>, <code>InvalidFrame</code>.</li><li>Application errors (2000+): <code>ApplicationError</code> (catch‑all; higher-level layers may define stable subcodes via metadata or payload).</li></ul><h2 id="error-frame-shape-binary" tabindex="-1">Error frame shape (binary) <a class="header-anchor" href="#error-frame-shape-binary" aria-label="Permalink to “Error frame shape (binary)”">​</a></h2><ul><li><code>ErrorFrame</code> (<code>t=3</code>): <code>code:uint16 LE</code>, <code>msgLen:uint32 LE</code>, <code>message:UTF-8</code>, optional opaque <code>details</code> (e.g. JSON/CBOR details).</li><li><code>id</code> SHOULD mirror the failing frame&#39;s <code>id</code> when correlating to a request/response; absent otherwise.</li><li><code>ts</code> OPTIONAL for diagnostics.</li></ul><h2 id="contract-for-senders" tabindex="-1">Contract for senders <a class="header-anchor" href="#contract-for-senders" aria-label="Permalink to “Contract for senders”">​</a></h2><ul><li>Use the narrowest code available; avoid overloading <code>ApplicationError</code> for protocol faults.</li><li>Message text SHOULD be short and stable enough for logs; do not leak secrets.</li><li>On version mismatch during handshake: send <code>UnsupportedVersion</code> then close.</li><li>On malformed input: send <code>InvalidFrame</code> with context in <code>message</code>; <code>details</code> MAY include a structured schema error.</li><li>When closing after a fatal error, prefer sending an <code>ErrorFrame</code> before <code>Control:Close</code> unless the transport is already unusable.</li></ul><h2 id="contract-for-receivers" tabindex="-1">Contract for receivers <a class="header-anchor" href="#contract-for-receivers" aria-label="Permalink to “Contract for receivers”">​</a></h2><ul><li>Treat <code>ProtocolViolation</code> and <code>UnsupportedVersion</code> as fatal; close the transport after emitting diagnostics.</li><li><code>InvalidFrame</code> MAY be fatal or MAY trigger best-effort recovery if the frame boundary is intact; if recovery is unsafe, close.</li><li><code>ApplicationError</code> is non-fatal to the transport; the caller decides whether to retry.</li><li>If <code>id</code> is present, route the error to the correlated request/stream; otherwise emit as connection-level fault.</li></ul><h2 id="retryability-and-mapping" tabindex="-1">Retryability and mapping <a class="header-anchor" href="#retryability-and-mapping" aria-label="Permalink to “Retryability and mapping”">​</a></h2><ul><li>Retryable: typically <code>ApplicationError</code> with explicit higher-level hint; protocol spec itself is neutral.</li><li>Non-retryable: <code>UnsupportedVersion</code>, repeated <code>ProtocolViolation</code>, structurally invalid frames.</li><li>WebSocket mapping (guidance): <ul><li>Close with <code>1002</code> (protocol error) for <code>ProtocolViolation</code>/<code>InvalidFrame</code>.</li><li>Close with <code>1003</code> (unsupported data) for <code>UnsupportedVersion</code>.</li><li>Preserve <code>ErrorFrame.message</code> in close reason when size allows; otherwise emit to logs only.</li></ul></li></ul><h2 id="security-considerations" tabindex="-1">Security considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to “Security considerations”">​</a></h2><ul><li>Size: receivers MAY cap <code>ErrorFrame.details</code> (e.g. ≤ 16 KiB) to prevent abuse.</li><li>Untrusted text: treat <code>message</code> as untrusted; escape before surfacing in UIs.</li><li>Rate limit: throttle repeated errors from a peer to avoid log/CPU DoS.</li></ul>',14)])])}const f=r(i,[["render",l]]);export{m as __pageData,f as default};
